    handleSearch = (value) => {
        const { projects } = this.state;

        if (!value.trim()) {
            this.setState({
                searchValue: value,
                filteredProjects: projects
            });
            return;
        }

        const searchTerm = value.toLowerCase();
        const filteredProjects = projects.filter(project => {
            // Search in project name, ID, code, and organization units
            const projectMatches = project.displayName.toLowerCase().includes(searchTerm) ||
                project.id.toLowerCase().includes(searchTerm) ||
                (project.code && project.code.toLowerCase().includes(searchTerm));

            // Search in assigned organization units
            const orgUnitMatches = project.organisationUnits && project.organisationUnits.some(orgUnit =>
                orgUnit.displayName.toLowerCase().includes(searchTerm) ||
                orgUnit.id.toLowerCase().includes(searchTerm)
            );

            return projectMatches || orgUnitMatches;
        });

        this.setState({
            searchValue: value,
            filteredProjects: filteredProjects
        });
    };

